// @ts-nocheck
// ===== SB02 อ่าน Tags จาก PLC Mitsubishi 192.168.0.100 =====
// ลองทุกรูปแบบอัตโนมัติ: SLMP 3E Binary / 3E ASCII / 4E Binary / Modbus TCP (unit 1,0,255)
// เจอแบบที่ใช้ได้แล้วจำไว้ ต่อค้างไว้ใช้ซ้ำ (PLC รับทีละ 1 connection)
// Output 1 = ค่าสำหรับ Dashboard | Output 2 = Tags (ชื่อ + ค่า) | Output 3 = ผลค้นหา / error
const HOST  = "192.168.0.100";
const PORTS = [5100, 502, 5000, 5001, 5002, 5003, 5004, 5005, 5006, 5007, 5010, 5011, 5012, 1025, 1026, 4999, 8000, 5015];
const TMO   = 2500;
const PTS   = 332;                          // D0..D331

// รายการ Tags (D = เลข register, bits = 16/32, div = หารเพื่อได้ค่าจริง)
const TAGS = [
    { key: "status", d: 0,   bits: 16, name: "สถานะเครื่อง (1=OP 2=EG 3=SV)" },
    { key: "ng",     d: 60,  bits: 16, name: "NG" },
    { key: "ccdNg",  d: 300, bits: 32, name: "CCD 檢測異常 (CCD NG)" },
    { key: "ccdOk",  d: 320, bits: 16, name: "CCD 檢測 OK" },
    { key: "total",  d: 322, bits: 32, name: "入球總數 ยอดรวม (Total)" },
    { key: "rate",   d: 330, bits: 32, div: 10, name: "定位率 % (Positioning rate)" }
];

if (context.get("busy")) return null;
context.set("busy", true);

// ---------- การเชื่อมต่อแบบค้างไว้ ----------
function getConn(port) {
    let c = context.get("conn");
    if (c && c.port === port && !c.dead) return Promise.resolve(c);
    if (c && c.sock) { try { c.sock.destroy(); } catch (e) {} }
    return new Promise(res => {
        const s = new net.Socket();
        c = { port, sock: s, buf: Buffer.alloc(0), wait: null, dead: false, ready: false, t0: Date.now() };
        const kill = (why) => { if (!c.dead) c.lifeMs = Date.now() - c.t0; c.dead = true; c.why = c.why || why; if (c.wait) { const w = c.wait; c.wait = null; w({ err: why }); } };
        s.setNoDelay(true); s.setKeepAlive(true, 10000);
        s.on("data", d => { c.buf = Buffer.concat([c.buf, d]); if (c.wait) c.wait(); });
        s.on("error", e => kill(e.code || e.message));
        s.on("close", () => kill("closed"));
        const t = setTimeout(() => { if (!c.ready) { kill("connect timeout"); s.destroy(); res(c); } }, TMO);
        s.connect(port, HOST, () => { clearTimeout(t); c.ready = true; c.t0 = Date.now(); res(c); });
        context.set("conn", c);
    });
}
function ask(c, frame, need) {
    return new Promise(res => {
        if (c.dead || !c.ready) return res({ err: c.why === "closed" ? "PLC ตัดสาย" : "ไม่ได้เชื่อมต่อ" });
        c.buf = Buffer.alloc(0);
        const t = setTimeout(() => { c.wait = null; c.dead = true; try { c.sock.destroy(); } catch (e) {} res({ err: "ไม่ตอบ (timeout)" }); }, TMO);
        c.wait = (fail) => {
            if (fail && fail.err) { clearTimeout(t); return res({ err: fail.err === "closed" ? "PLC ตัดสายหลังส่งคำสั่ง" : fail.err }); }
            if (need(c.buf)) { clearTimeout(t); c.wait = null; const b = c.buf; c.buf = Buffer.alloc(0); res({ buf: b }); }
        };
        c.sock.write(frame);
    });
}
const sleep = ms => new Promise(r => setTimeout(r, ms));

// ---------- รูปแบบ frame ----------
function mc3eBin(start, n) {
    const b = Buffer.alloc(21);
    b.writeUInt16LE(0x0050, 0); b[2] = 0; b[3] = 0xFF; b.writeUInt16LE(0x03FF, 4); b[6] = 0;
    b.writeUInt16LE(12, 7); b.writeUInt16LE(0x0010, 9); b.writeUInt16LE(0x0401, 11); b.writeUInt16LE(0, 13);
    b.writeUIntLE(start, 15, 3); b[18] = 0xA8; b.writeUInt16LE(n, 19); return b;
}
function mc4eBin(start, n) {
    const b = Buffer.alloc(25);
    b.writeUInt16LE(0x0054, 0); b.writeUInt16LE(0x0001, 2); b.writeUInt16LE(0, 4);
    b[6] = 0; b[7] = 0xFF; b.writeUInt16LE(0x03FF, 8); b[10] = 0;
    b.writeUInt16LE(12, 11); b.writeUInt16LE(0x0010, 13); b.writeUInt16LE(0x0401, 15); b.writeUInt16LE(0, 17);
    b.writeUIntLE(start, 19, 3); b[22] = 0xA8; b.writeUInt16LE(n, 23); return b;
}
const hx = (v, w) => v.toString(16).toUpperCase().padStart(w, "0");
function mc3eAscii(start, n) { return Buffer.from("500000FF03FF00" + "0018" + "0010" + "0401" + "0000" + "D*" + String(start).padStart(6, "0") + hx(n, 4), "latin1"); }

async function readMcBin(c, is4e) {
    const off = is4e ? 4 : 0;
    const r = await ask(c, is4e ? mc4eBin(0, PTS) : mc3eBin(0, PTS), b => b.length >= 11 + off && b.length >= 9 + off + b.readUInt16LE(7 + off));
    if (r.err) return r;
    if (r.buf.readUInt16LE(0) !== (is4e ? 0x00D4 : 0x00D0)) return { err: "ตอบมาแต่ไม่ใช่ MC (" + r.buf.slice(0, 8).toString("hex") + ")" };
    const end = r.buf.readUInt16LE(9 + off);
    if (end !== 0) return { err: "MC end code 0x" + end.toString(16).toUpperCase() };
    const v = []; for (let i = 0; i < PTS; i++) v.push(r.buf.readUInt16LE(11 + off + i * 2)); return { v };
}
async function readMcAscii(c) {
    const r = await ask(c, mc3eAscii(0, PTS), b => b.length >= 18 && b.length >= 18 + parseInt(b.toString("latin1", 14, 18), 16));
    if (r.err) return r;
    const s = r.buf.toString("latin1");
    if (!s.startsWith("D000")) return { err: "ตอบมาแต่ไม่ใช่ MC ASCII (" + s.slice(0, 12) + ")" };
    const end = s.slice(18, 22);
    if (end !== "0000") return { err: "MC end code 0x" + end };
    const v = []; for (let i = 0; i < PTS; i++) v.push(parseInt(s.substr(22 + i * 4, 4), 16)); return { v };
}
let tid = 0;
async function readMb(c, unit) {
    const v = new Array(PTS).fill(0);
    for (const [s, n] of [[0, 1], [60, 1], [300, 32]]) {
        tid = (tid + 1) & 0xFFFF;
        const r = await ask(c, Buffer.from([tid >> 8, tid & 255, 0, 0, 0, 6, unit, 3, s >> 8, s & 255, n >> 8, n & 255]),
                            b => b.length >= 9 && b.length >= 6 + b.readUInt16BE(4));
        if (r.err) return r;
        if (r.buf[7] !== 3) return { err: r.buf[7] === 0x83 ? "Modbus exception " + r.buf[8] : "ไม่ใช่ Modbus" };
        for (let i = 0; i < n; i++) v[s + i] = r.buf.readUInt16BE(9 + i * 2);
    }
    return { v };
}
const PROTOS = ["MC3E", "MC3E-ASCII", "MC4E", "MB1", "MB0", "MB255"];
function readWith(c, proto) {
    if (proto === "MC3E") return readMcBin(c, false);
    if (proto === "MC4E") return readMcBin(c, true);
    if (proto === "MC3E-ASCII") return readMcAscii(c);
    return readMb(c, +proto.slice(2));
}
async function readOnce(cfg) {
    const c = await getConn(cfg.port);
    if (c.dead) return { err: "ต่อ port " + cfg.port + " ไม่ได้ (" + (c.why || "?") + ")", closedPort: true };
    return readWith(c, cfg.proto);
}

async function discover() {
    const report = [];
    for (const port of PORTS) {
        for (const proto of PROTOS) {
            node.status({ fill: "blue", shape: "ring", text: "กำลังหา... " + port + " " + proto });
            const r = await readOnce({ proto, port });
            if (r.v) { report.push("✓ " + port + " " + proto + " ใช้ได้"); return { cfg: { proto, port }, report, v: r.v }; }
            const c = context.get("conn");
            report.push(port + " " + proto + ": " + r.err);
            if (c) { c.dead = true; try { c.sock.destroy(); } catch (e) {} }
            if (r.closedPort) break;                 // port ปิด ข้ามไป port ถัดไป
            await sleep(300);
        }
    }
    // ช่วยวิเคราะห์: ต่อได้แต่ PLC ตัดทุกแบบ
    if (report.some(s => /^502 .*ตัดสาย/.test(s)) && report.filter(s => /^502 /.test(s)).every(s => /ตัดสาย/.test(s))) {
        report.push("→ port 502 รับต่อแต่ตัดสายทุกแบบ: ใน GX Works3 ให้เช็ค External Device Configuration ว่า IP ปลายทางเป็น 192.168.0.2 (กล่องนี้) หรือ connection ถูกเครื่องอื่นใช้อยู่");
    }
    return { report };
}

function decode(v) {
    const tags = {}, out = {};
    for (const t of TAGS) {
        let x = t.bits === 32 ? v[t.d] + v[t.d + 1] * 65536 : v[t.d];
        if (t.div) x = x / t.div;
        out[t.key] = x;
        tags[(t.bits === 32 ? "D" + t.d + "-" + (t.d + 1) : "D" + t.d) + " " + t.name] = x;
    }
    out.ok = Math.max(0, out.total - out.ng);
    out.statusText = { 0: "STOP", 1: "OP", 2: "EG", 3: "SV" }[out.status] || ("?" + out.status);
    out.time = new Date().toLocaleString("en-GB");
    tags["OK (Total - NG)"] = out.ok;
    return { out, tags };
}

(async () => {
    try {
        let cfg = context.get("cfg"), v;
        if (!cfg) {
            if (Date.now() < (context.get("retryAt") || 0)) return;
            const d = await discover();
            node.send([null, null, { topic: "ผลค้นหา " + HOST, payload: d.report }]);
            if (!d.cfg) { node.status({ fill: "red", shape: "ring", text: "หา PLC ไม่เจอ ดูผลใน Debug (ลองใหม่ทุก 60 วิ)" }); context.set("retryAt", Date.now() + 60000); return; }
            cfg = d.cfg; context.set("cfg", cfg); v = d.v;
        } else {
            let r = await readOnce(cfg);
            if (!r.v) r = await readOnce(cfg);
            if (!r.v) {
                const n = (context.get("fail") || 0) + 1; context.set("fail", n);
                node.status({ fill: "red", shape: "ring", text: cfg.proto + ":" + cfg.port + " " + r.err + " (" + n + ")" });
                if (n >= 40) { context.set("cfg", null); context.set("fail", 0); }
                return;
            }
            v = r.v;
        }
        context.set("fail", 0);
        const { out, tags } = decode(v);

        // ---- CT (วินาที/ชิ้น) จาก Counter ที่เพิ่มขึ้นใน 60 วินาทีล่าสุด ----
        const WIN = 60000, now = Date.now();
        let hist = (context.get("hist") || []).filter(h => now - h.t <= WIN * 2);
        const last = hist[hist.length - 1];
        if (last && out.total < last.c) hist = [];
        hist.push({ t: now, c: out.total });
        context.set("hist", hist);
        const base = hist.find(h => now - h.t <= WIN) || hist[0];
        const dC = out.total - base.c, dT = (now - base.t) / 1000;
        if (dC > 0 && dT >= 10) {
            out.ct = Math.round(dT / dC * 100) / 100;
            out.pcsPerMin = Math.round(dC / dT * 60 * 10) / 10;
            context.set("lastCt", out.ct);
        } else {
            out.ct = dT >= 10 ? null : (context.get("lastCt") != null ? context.get("lastCt") : null);
            out.pcsPerMin = dT >= 10 ? 0 : null;
        }
        tags["CT วินาที/ชิ้น (คำนวณ)"] = out.ct;
        tags["ชิ้น/นาที (คำนวณ)"] = out.pcsPerMin;
        tags["อ่านด้วย"] = cfg.proto + " port " + cfg.port;
        tags["เวลา"] = out.time;

        flow.set("sb02", out); flow.set("sb02_ok", Date.now()); flow.set("sb02_tags", tags);
        node.status({ fill: "green", shape: "dot", text: cfg.proto + ":" + cfg.port + " | " + out.statusText + " Total " + out.total + " NG " + out.ng + " CT " + (out.ct != null ? out.ct : "-") + "s" });
        node.send([{ topic: "SB02", payload: out }, { topic: "SB02 Tags", payload: tags }, null]);
    } catch (e) {
        node.status({ fill: "red", shape: "ring", text: String(e.message || e) });
        node.send([null, null, { topic: "error", payload: String(e.stack || e) }]);
    } finally {
        context.set("busy", false);
    }
})();
return null;

